package vn.hust.restaurant.service;
import java.awt.print.*;import java.text.*;import java.util.*;import javax.swing.*;import vn.hust.restaurant.config.AppConfig;
public class InvoicePrintService{public void print(Map<String,Object> invoice)throws Exception{JTextPane pane=new JTextPane();pane.setContentType("text/html");pane.setText(html(invoice));pane.setEditable(false);PrinterJob job=PrinterJob.getPrinterJob();job.setJobName("Hoa don "+invoice.get("MaHoaDonCode"));job.setPrintable(pane.getPrintable(null,null));if(job.printDialog())job.print();}public String html(Map<String,Object>m){StringBuilder b=new StringBuilder("<html><body style='font-family:sans-serif;width:280px'><h2 style='text-align:center'>").append(AppConfig.app("restaurant.name","Nhà hàng")).append("</h2><p>");m.forEach((k,v)->b.append("<b>").append(k).append(":</b> ").append(v==null?"":v).append("<br>"));return b.append("</p><p style='text-align:center'>Cảm ơn quý khách!</p></body></html>").toString();}}
